export type Box=[number,number,number,number]; export function iou(a:Box,b:Box){const area=(v:Box)=>(v[2]-v[0])*(v[3]-v[1]);if([a,b].some(v=>v[2]<=v[0]||v[3]<=v[1]))throw new Error("Positive areas required");const intersection=Math.max(0,Math.min(a[2],b[2])-Math.max(a[0],b[0]))*Math.max(0,Math.min(a[3],b[3])-Math.max(a[1],b[1]));const union=area(a)+area(b)-intersection;return {intersection,union,value:intersection/union};} export function run(mode:number){const a:Box=[0,0,2,2],b:Box=mode===1?[3,0,5,2]:mode===2?[0,0,2,2]:[1,0,3,2];return {a,b,...iou(a,b)};}

function Picture({mode}:{mode:number}){const r=m.run(mode);return <svg className={s.plot} viewBox="0 0 280 112" role="img" aria-label="Overlap is a fraction — worked example">{[r.a,r.b].map((b,i)=><g key={i}><rect x={10+b[0]*28} y={24+i*3} width={(b[2]-b[0])*28} height="48" className={i===0?s.box:s.overlap}/><text x={14+b[0]*28} y={19+i*69}>{i===0?'A':'B'}</text></g>)}<text x="179" y="34">∩={r.intersection}</text><text x="179" y="59">∪={r.union}</text><text x="179" y="84">IoU={f(r.value,3)}</text></svg>;}

Locked inputs: A=[0,0,2,2], B=[1,0,3,2], half-open boxes. Match if IoU≥threshold; class correctness remains separate.
